// Synthetic fixture v1. Auth IDs are generated by supported Auth administration.
export const fixtureVersion = 'skillarc-synthetic-v1';
export const fixtureId = n => `91000000-0000-4000-8000-${String(n).padStart(12, '0')}`;
export const accountDefinitions = [
  ['student', 'STUDENT', 0], ['faculty', 'FACULTY', 0], ['admin', 'INSTITUTION_ADMIN', 0],
  ['empty', 'STUDENT', 0], ['withdrawn', 'STUDENT', 0],
  ['student-au', 'STUDENT', 1], ['faculty-au', 'FACULTY', 1], ['admin-au', 'INSTITUTION_ADMIN', 1],
].map(([name, role, campus]) => ({ name, role, campus, email: `${name}@skillarc-fixtures.invalid` }));
const literal = value => value === null ? 'NULL' : typeof value === 'boolean' || typeof value === 'number' ? String(value) : `'${String(value).replaceAll("'", "''")}'`;
const json = value => `${literal(JSON.stringify(value))}::jsonb`;
export function fixtureSql(accounts, anchor = new Date()) {
  for (const a of accountDefinitions) if (!/^[a-f0-9-]{36}$/.test(accounts[a.name] || '')) throw new Error('Missing fixture Auth identity');
  const date = offset => new Date(Date.UTC(anchor.getUTCFullYear(), anchor.getUTCMonth(), anchor.getUTCDate() + offset)).toISOString().slice(0, 10);
  const rows = [];
  function insert(table, record, conflict = 'id', refresh = []) {
    const keys = Object.keys(record);
    const values = keys.map(k => record[k]?.sql ?? literal(record[k]));
    rows.push(`INSERT INTO public.${table} (${keys.join(',')}) VALUES (${values.join(',')}) ON CONFLICT (${conflict}) DO ${refresh.length ? 'UPDATE SET ' + refresh.map(k => `${k}=EXCLUDED.${k}`).join(',') : 'NOTHING'};`);
  }
  rows.push('DO $fixture_v1$ BEGIN');
  // Refuse a collision with unrelated data; there is no delete/reset path.
  rows.push(`IF EXISTS(SELECT 1 FROM public.organizations WHERE id IN (${literal(fixtureId(1))},${literal(fixtureId(2))}) AND name NOT LIKE '[Synthetic v1]%') THEN RAISE EXCEPTION 'Fixture ownership collision'; END IF;`);
  for (let campus = 0; campus < 2; campus++) {
    const base = 100 + campus * 100;
    const id = n => fixtureId(base + n);
    const student = accounts[campus ? 'student-au' : 'student'];
    const faculty = accounts[campus ? 'faculty-au' : 'faculty'];
    insert('organizations', { id: fixtureId(campus + 1), name: `[Synthetic v1] ${campus ? 'Australia' : 'India'} organization` });
    insert('institutions', { id: id(0), organization_id: fixtureId(campus + 1), name: `[Synthetic v1] ${campus ? 'Sydney example campus' : 'India example campus'}`, domain: campus ? 'australia.fixture.invalid' : 'india.fixture.invalid' });
    // Timezone migration is a separate reviewed prerequisite, not an inferred real campus zone.
    rows.push(`IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_name='institutions' AND table_schema='public' AND column_name='academic_time_zone') THEN UPDATE public.institutions SET academic_time_zone=${literal(campus ? 'Australia/Sydney' : 'Asia/Kolkata')} WHERE id=${literal(id(0))}; END IF;`);
    insert('departments', { id: id(1), institution_id: id(0), name: '[Synthetic v1] Computing' });
    insert('programs', { id: id(2), department_id: id(1), institution_id: id(0), organization_id: fixtureId(campus + 1), name: '[Synthetic v1] Applied Computing' });
    for (const account of accountDefinitions.filter(a => a.campus === campus)) {
      const uid = accounts[account.name];
      rows.push(`IF EXISTS(SELECT 1 FROM public.users WHERE id=${literal(uid)} AND (email IS DISTINCT FROM ${literal(account.email)} OR organization_id IS DISTINCT FROM ${literal(fixtureId(campus + 1))}::uuid)) THEN RAISE EXCEPTION 'Fixture user collision'; END IF;`);
      insert('users', { id: uid, institution_id: id(0), department_id: id(1), name: `[Synthetic v1] ${account.name}`, email: account.email, role: account.role, organization_id: fixtureId(campus + 1), is_active: true });
      if (account.role !== 'STUDENT') insert('staff', { id: uid, institution_id: id(0), employee_id: `SYN-${account.name}` });
    }
    insert('sections', { id: id(3), name: '[Synthetic v1] Section A', semester: 1, program_id: id(2), institution_id: id(0), faculty_advisor_id: faculty });
    for (const a of accountDefinitions.filter(a => a.campus === campus && a.role === 'STUDENT')) {
      insert('students', { id: accounts[a.name], institution_id: id(0), program_id: id(2), section_id: a.name === 'empty' ? null : id(3), semester: 1, registration_number: `SYN-${a.name}` });
    }
    insert('subjects', { id: id(4), institution_id: id(0), program_id: id(2), name: '[Synthetic v1] Data structures and practical problem solving', code: 'SYN101', semester: 1, credits: 4, subject_type: 'THEORY' });
    insert('faculty_subjects', { id: id(5), institution_id: id(0), faculty_id: faculty, subject_id: id(4), section_id: id(3), semester: 1, academic_year: `${anchor.getUTCFullYear()}-${anchor.getUTCFullYear()+1}` });
    insert('institution_timetable_settings', { institution_id: id(0), period_timings: { sql: json([{id:'P1',label:'Period 1',time:'09:00 - 10:00'},{id:'P2',label:'Period 2',time:'10:15 - 11:15'}]) } }, 'institution_id');
    insert('enrolments', { id: id(6), student_id: student, institution_id: id(0), program_id: id(2), section_id: id(3), status: 'ENROLLED', started_at: date(-30), ended_at: date(180) }, 'id', ['started_at','ended_at']);
    insert('enrolment_units', { id: id(7), enrolment_id: id(6), subject_id: id(4), status: 'ACTIVE', trainer_id: faculty, planned_start: date(-30), planned_end: date(180) }, 'id', ['planned_start','planned_end']);
    if (!campus) insert('enrolments', { id: id(8), student_id: accounts.withdrawn, institution_id: id(0), program_id: id(2), section_id: id(3), status:'WITHDRAWN', started_at:date(-90), ended_at:date(-30) }, 'id', ['started_at','ended_at']);
    const mondayOffset = -((anchor.getUTCDay() + 6) % 7);
    for (let week=0; week<2; week++) insert('timetable_weeks', { id:id(10+week), institution_id:id(0), section_id:id(3), semester:1, week_number:week+1, title:`[Synthetic v1] Week ${week+1}`, start_date:date(mondayOffset+7*week), end_date:date(mondayOffset+7*week+6) }, 'id', ['start_date','end_date']);
    for (let day=0; day<5; day++) {
      insert('timetable_slots', { id:id(20+day), institution_id:id(0), organization_id:fixtureId(campus+1), section_id:id(3), subject_id:id(4), faculty_id:faculty, semester:1, day:['Monday','Tuesday','Wednesday','Thursday','Friday'][day], period:1, room:'Synthetic room 101', delivery_mode:'ON_CAMPUS' });
      insert('timetable_slots', { id:id(25+day), institution_id:id(0), organization_id:fixtureId(campus+1), section_id:id(3), subject_id:id(4), faculty_id:faculty, semester:1, week_id:id(11), day:['Monday','Tuesday','Wednesday','Thursday','Friday'][day], period:2, room:'Synthetic room 202', delivery_mode:'HYBRID' });
    }
    insert('academic_calendar_events', { id:id(30), institution_id:id(0), title:'[Synthetic v1] Campus closure', event_type:'PUBLIC_HOLIDAY', start_date:date(3), end_date:date(3), affects_classes:true }, 'id', ['start_date','end_date']);
    // Existing due_date is timestamp WITHOUT timezone: intentionally ambiguous.
    // Known instants live in the fixture manifest until #55 defines their canonical representation.
    for (let n=0;n<5;n++) insert('assignments', { id:id(40+n), subject_id:id(4), faculty_id:faculty, title:['[Synthetic v1] Regular practice','[Synthetic v1] Quiz summary','[Synthetic v1] Coding summary','[Synthetic v1] No deadline','[Synthetic v1] Ambiguous deadline'][n], type:['Assignment','Quiz','Coding','Assignment','Assignment'][n], description:'Synthetic test work; external execution is disabled.', due_date:n===3?null:`${date(n===0?-1:2)} 12:00:00`, section_ids:{sql:`ARRAY[${literal(id(3))}::uuid]`} }, 'id', ['due_date']);
    insert('submissions', { id:id(45), assignment_id:id(40), student_id:student, status:'graded', grade:85, feedback:'[Synthetic v1] Reviewed example' });
    insert('subject_announcements', { id:id(46), subject_id:id(4), faculty_id:faculty, title:'[Synthetic v1] Welcome', description:'Read the practice material before class.', section_ids:{sql:`ARRAY[${literal(id(3))}::uuid]`} });
    insert('resources', { id:id(47), subject_id:id(4), faculty_id:faculty, title:'[Synthetic v1] Resource availability example', file_url:'https://resources.fixture.invalid/example.pdf' });
    insert('announcements', { id:id(48), institution_id:id(0), created_by:faculty, title:'[Synthetic v1] Campus news', content:'This is a synthetic testing environment.' });
    insert('attendance_sessions', { id:id(50), subject_id:id(4), faculty_id:faculty, section_id:id(3), attendance_date:date(-1), period:1 }, 'id', ['attendance_date']);
    insert('attendance_records', { id:id(51), session_id:id(50), student_id:student, status:'PRESENT', notes:'[Synthetic v1]' });
    insert('leave_applications', { id:id(52), institution_id:id(0), student_id:student, section_id:id(3), advisor_id:faculty, status:'PENDING', reason:'[Synthetic v1] Example leave', from_date:date(5), to_date:date(6) }, 'id', ['from_date','to_date']);
    insert('grade_columns', { id:id(53), subject_id:id(4), created_by:faculty, title:'[Synthetic v1] Practice result', type:'assignment', max_score:100, weight:100 });
    insert('grade_entries', { id:id(54), column_id:id(53), student_id:student, score:85, graded_by:faculty, feedback:'Synthetic result; release workflow is separately verified.' });
  }
  rows.push('END $fixture_v1$;');
  return rows.join('\n');
}
